args.CommandLine:
$ErrorActionPreference = 'Continue'
Write-Output '=== STEP 4: TEMP CLEANUP ==='
$tempDirs = @(
  'C:\Users\Admin\AppData\Local\Temp',
  'C:\Windows\Temp',
  'C:\Windows\SystemTemp',
  'C:\Windows\SoftwareDistribution\Download',
  'C:\Users\Admin\AppData\Local\D3DSCache',
  'C:\Users\Admin\AppData\Local\Microsoft\Windows\INetCache',
  'C:\Windows\Logs'
)

foreach ($dir in $tempDirs) {
  if (Test-Path -LiteralPath $dir) {
    $beforeFiles = @(Get-ChildItem -LiteralPath $dir -Recurse -Force -File -ErrorAction SilentlyContinue)
    $beforeBytes = ($beforeFiles | Measure-Object -Property Length -Sum).Sum
    Get-ChildItem -LiteralPath $dir -Force -ErrorAction SilentlyContinue | ForEach-Object {
      Remove-Item -LiteralPath $_.FullName -Recurse -Force -ErrorAction SilentlyContinue
    }
    $afterFiles = @(Get-ChildItem -LiteralPath $dir -Recurse -Force -File -ErrorAction SilentlyContinue)
    $afterBytes = ($afterFiles | Measure-Object -Property Length -Sum).Sum
    $freedMB = [math]::Round(($beforeBytes - $afterBytes) / 1MB, 2)
    $remMB = [math]::Round($afterBytes / 1MB, 2)
    Write-Output "$dir | BeforeFiles=$($beforeFiles.Count) | AfterFiles=$($afterFiles.Count) | FreedMB=$freedMB | LockedRemMB=$remMB"
  }
}

Write-Output '=== EMPTY RECYCLE BIN ==='
Clear-RecycleBin -DriveLetter C -Force -ErrorAction SilentlyContinue
$sh = New-Object -ComObject Shell.Application
$rb = $sh.NameSpace(10)
$rbCount = @($rb.Items()).Count
if ($rbCount -gt 0) {
  Get-ChildItem -LiteralPath 'C:\$Recycle.Bin' -Force -ErrorAction SilentlyContinue | ForEach-Object {
    Get-ChildItem -LiteralPath $_.FullName -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -ne 'desktop.ini' } | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue
  }
  $rbCount = @($sh.NameSpace(10).Items()).Count
}
$rbRaw = Get-ChildItem -LiteralPath 'C:\$Recycle.Bin' -Recurse -Force -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -ne 'desktop.ini' }
$rbRawCount = @($rbRaw).Count
$rbRawMB = [math]::Round((($rbRaw | Measure-Object -Property Length -Sum).Sum) / 1MB, 2)
Write-Output "RecycleBinItems=$rbCount | RecycleBinRawNonIniFiles=$rbRawCount | RawMB=$rbRawMB"

$ErrorActionPreference = 'SilentlyContinue'
$p = 'C:\Program Files (x86)\Microsoft\EdgeWebView\Temp\source1596_1499818134\MSEDGE.7z'
if (Test-Path -LiteralPath $p) {
  $it = Get-Item -LiteralPath $p -Force
  Write-Output "Target: $($it.FullName) | SizeMB=$([math]::Round($it.Length/1MB,2)) | Creation=$($it.CreationTime) | LastWrite=$($it.LastWriteTime)"
} else {
  Write-Output "Not found: $p"
}
Write-Output '=== EdgeWebView ROOT & TEMP CONTENTS ==='
Get-ChildItem 'C:\Program Files (x86)\Microsoft\EdgeWebView' -Force | ForEach-Object { Write-Output "Root: $($_.Name)" }
Get-ChildItem 'C:\Program Files (x86)\Microsoft\EdgeWebView\Temp' -Recurse -Force | ForEach-Object {
