Get-ChildItem 'C:\Program Files (x86)\Microsoft\EdgeWebView\Application' -Directory -Force | ForEach-Object { Write-Output "AppDir: $($_.Name)" }
Get-Process | Where-Object { $_.Name -match 'edge|webview|setup' } | Select-Object Name, Id, Path | Format-Table -AutoSize
Get-Service | Where-Object { $_.Name -match 'edge' -or $_.DisplayName -match 'edge' } | Select-Object Name, DisplayName, Status, StartType | Format-Table -AutoSize

$ErrorActionPreference = 'SilentlyContinue'
Write-Output '=== MICROSOFT EDGE / EDGECORE / EDGEWEBVIEW / APPX ON C ==='
foreach ($base in @('C:\Program Files (x86)\Microsoft', 'C:\Program Files\Microsoft', 'C:\ProgramData\Microsoft', 'C:\Users\Admin\AppData\Local\Microsoft')) {
  if (Test-Path -LiteralPath $base) {
    Get-ChildItem -LiteralPath $base -Force | Where-Object { $_.Name -match 'Edge|Temp|Core' } | ForEach-Object {
