Get-ChildItem 'C:\Windows\SystemApps' -Force | Where-Object { $_.Name -match 'Edge|WebView' } | ForEach-Object { Write-Output "SystemApp: $($_.FullName)" }
Get-AppxPackage -AllUsers | Where-Object { $_.Name -match 'Edge' } | Select-Object Name, PackageFullName, Status | Format-Table -AutoSize
Get-Service | Where-Object { $_.Name -match 'edge' -or $_.DisplayName -match 'edge' } | Format-Table Name, DisplayName, Status, StartType -AutoSize
Get-ScheduledTask | Where-Object { $_.TaskName -match 'edge' -or $_.TaskPath -match 'edge' } | Format-Table TaskPath, TaskName, State -AutoSize
Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*','HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*' | Where-Object { $_.DisplayName -match 'Edge' } | Select-Object PSChildName, DisplayName, DisplayVersion, InstallLocation, UninstallString | Format-List

$ErrorActionPreference = 'SilentlyContinue'
Write-Output '=== GOOGLE UPDATE / GOOGLEUPDATER / CHROME PROCESSES & FILES ==='
Get-Process | Where-Object { $_.Name -match 'google|chrome|updater' } | Select-Object Name, Id, Path | Format-Table -AutoSize
foreach ($gbase in @('C:\Program Files\Google', 'C:\Program Files (x86)\Google', 'C:\ProgramData\Google', 'C:\Users\Admin\AppData\Local\Google')) {
  if (Test-Path -LiteralPath $gbase) {
    Get-ChildItem -LiteralPath $gbase -Recurse -Depth 2 -Force | ForEach-Object {
      Write-Output "GooglePath: $($_.FullName)"
    }
  }
