Write-Output '=== GOOGLE SERVICES & SCHEDULED TASKS ==='
Get-Service | Where-Object { $_.Name -match 'gupdate|google|chrome' -or $_.DisplayName -match 'google|chrome' } | Select-Object Name, DisplayName, Status, StartType | Format-Table -AutoSize
Get-ScheduledTask | Where-Object { $_.TaskName -match 'google|chrome|update' -or $_.TaskPath -match 'google' } | Select-Object TaskPath, TaskName, State | Format-Table -AutoSize

Write-Output '=== GOOGLE POLICIES & CHROME APP VERSION ==='
foreach ($pk in @('HKLM:\SOFTWARE\Policies\Google', 'HKCU:\SOFTWARE\Policies\Google', 'HKLM:\SOFTWARE\Google', 'HKLM:\SOFTWARE\WOW6432Node\Google', 'HKCU:\SOFTWARE\Google')) {
  if (Test-Path -LiteralPath $pk) {
    Write-Output "--- $pk ---"
    Get-ChildItem $pk -Recurse | ForEach-Object {
      Write-Output "Key: $($_.Name)"
      Get-ItemProperty $_.PSPath | Format-List
