$ErrorActionPreference = 'SilentlyContinue'
Write-Output '=== SCHEDULED TASK \Edge ==='
if (Test-Path 'C:\Windows\System32\Tasks\Edge') {
  Get-Content 'C:\Windows\System32\Tasks\Edge'
}

Write-Output '=== EdgeCore & EdgeUpdate CONTENTS ==='
Get-ChildItem 'C:\Program Files (x86)\Microsoft\EdgeCore\157.0.4341.46' -Force
Get-ChildItem 'C:\ProgramData\Microsoft\EdgeUpdate' -Recurse -Force
Get-ChildItem 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\EdgeUpdate' -Force
Get-ChildItem 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*','HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*' | Where-Object { $_.PSChildName -match 'Edge' -or $_.DisplayName -match 'Edge' } | Format-List PSPath, DisplayName, DisplayVersion

