Get-Service | Where-Object { $_.Name -match 'google|gupdate' -or $_.DisplayName -match 'google|gupdate' } | Format-Table Name, DisplayName, Status, StartType -AutoSize
Get-ScheduledTask | Where-Object { $_.TaskName -match 'google' -or $_.TaskPath -match 'google' } | Format-Table TaskPath, TaskName, State -AutoSize
Get-ChildItem 'C:\Windows\System32\Tasks' -Recurse -Force | Where-Object { $_.FullName -match 'google' } | ForEach-Object { Write-Output "GoogleTaskFile: $($_.FullName)" }
foreach ($k in @('HKLM:\SOFTWARE\Policies\Google', 'HKCU:\SOFTWARE\Policies\Google', 'HKLM:\SOFTWARE\Google\Update', 'HKLM:\SOFTWARE\WOW6432Node\Google\Update')) {
  Write-Output "Exists($k) = $(Test-Path $k)"
  if (Test-Path $k) { Get-ChildItem $k -Recurse | Format-List Name }
}

Get-ChildItem 'C:\Windows\System32\Tasks\GoogleUserPEH' -Force | ForEach-Object {
  Write-Output "Task: $($_.FullName)"
  Get-Content $_.FullName
}
Get-Service | Where-Object { $_.Name -match 'GoogleUpdater' } | Format-List Name, Status, StartType
Get-Process | Where-Object { $_.Name -match 'updater|GoogleUpdate' } | Format-List Name, Id, Path

$ErrorActionPreference = 'Continue'
Write-Output '=== EDGE LEFTOVERS REMOVAL ==='
foreach ($ep in @(
  'C:\Program Files (x86)\Microsoft\EdgeWebView',
  'C:\Program Files (x86)\Microsoft\EdgeCore',
  'C:\Program Files (x86)\Microsoft\Temp',
  'C:\ProgramData\Microsoft\EdgeUpdate'
)) {
  if (Test-Path -LiteralPath $ep) {
    Remove-Item -LiteralPath $ep -Recurse -Force
    Write-Output "Removed: $ep (ExistsAfter=$(Test-Path -LiteralPath $ep))"
  }
}
if ((Test-Path -LiteralPath 'C:\Program Files (x86)\Microsoft') -and ((Get-ChildItem -LiteralPath 'C:\Program Files (x86)\Microsoft' -Force).Count -eq 0)) {
  Remove-Item -LiteralPath 'C:\Program Files (x86)\Microsoft' -Force
  Write-Output "Removed empty parent: C:\Program Files (x86)\Microsoft"
}
foreach ($erk in @(
  'HKLM:\SOFTWARE\WOW6432Node\Microsoft\EdgeUpdate',
  'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\Microsoft EdgeWebView'
)) {
  if (Test-Path -LiteralPath $erk) {
    Remove-Item -LiteralPath $erk -Recurse -Force
    Write-Output "Removed Edge reg: $erk"
  }
}

Write-Output '=== NUKE GOOGLE UPDATER SERVICES & TASKS ==='
Get-Process | Where-Object { $_.Name -match 'GoogleUpdate|updater' } | Stop-Process -Force -ErrorAction SilentlyContinue
foreach ($svc in @('GoogleUpdaterService157.0.8089.0', 'GoogleUpdaterInternalService157.0.8089.0')) {
  & sc.exe stop $svc | Out-Null
  & sc.exe delete $svc | Write-Output
}
Get-ScheduledTask | Where-Object { $_.TaskPath -like '\GoogleSystem*' } | ForEach-Object {
  Unregister-ScheduledTask -TaskName $_.TaskName -TaskPath $_.TaskPath -Confirm:$false
  Write-Output "Unregistered task: $($_.TaskPath)$($_.TaskName)"
}
foreach ($tf in @('C:\Windows\System32\Tasks\GoogleSystem', 'C:\Windows\System32\Tasks\GoogleUserPEH')) {
  if (Test-Path -LiteralPath $tf) {
    Remove-Item -LiteralPath $tf -Recurse -Force
    Write-Output "Removed task folder: $tf"
  }
}

Write-Output '=== REMOVE & ACL-LOCK GOOGLE UPDATER FOLDERS ==='
$lockDirs = @(
  'C:\Program Files (x86)\Google\GoogleUpdater',
  'C:\Program Files (x86)\Google\Update',
  'C:\Users\Admin\AppData\Local\Google\GoogleUpdater'
)
foreach ($ld in $lockDirs) {
  if (Test-Path -LiteralPath $ld) {
    & icacls $ld /reset /T /C /Q | Out-Null
    Remove-Item -LiteralPath $ld -Recurse -Force
  }
  New-Item -ItemType Directory -Path $ld -Force | Out-Null
  & icacls $ld /inheritance:r /deny "*S-1-5-18:(OI)(CI)F" /deny "*S-1-5-32-544:(OI)(CI)F" /deny "*S-1-5-32-545:(OI)(CI)F" | Out-Null
  Write-Output "ACL-locked empty dir: $ld (icacls exit=$LASTEXITCODE)"
}

Write-Output '=== APPLY ENTERPRISE GOOGLE UPDATE POLICIES ==='
$polRoots = @(
  'HKLM:\SOFTWARE\Policies\Google\Update',
  'HKLM:\SOFTWARE\WOW6432Node\Policies\Google\Update'
)
$vals = @{
  'AutoUpdateCheckPeriodMinutes' = 0
  'UpdateDefault' = 0
  'Update{8A69D345-D564-463C-AFF1-A69D9E530F96}' = 0
  'DisableAutoUpdateChecksCheckboxValue' = 1
}
foreach ($pr in $polRoots) {
  if (-not (Test-Path -LiteralPath $pr)) {
    New-Item -Path $pr -Force | Out-Null
  }
  foreach ($kv in $vals.GetEnumerator()) {
    New-ItemProperty -LiteralPath $pr -Name $kv.Key -Value $kv.Value -PropertyType DWord -Force | Out-Null
  }
  Write-Output "Applied 4 update-disable policies to: $pr"
}

$ErrorActionPreference = 'SilentlyContinue'
Write-Output '=== VERIFY EDGE LEFTOVERS REMOVED ==='
