}

Write-Output '=== VERIFY PROTECTED EXCLUSIONS INTACT ==='
Write-Output "ddudduddu\edge.exe procs=$((Get-Process | Where-Object { $_.Path -eq 'C:\ddudduddu\edge.exe' }).Count)"
Write-Output "Task_\Edge=$($null -ne (Get-ScheduledTask -TaskName 'Edge'))"
Write-Output "Win32WebViewHost=$((Test-Path -LiteralPath 'C:\Windows\SystemApps\Microsoft.Win32WebViewHost_cw5n1h2txyewy'))"
Write-Output "ChromeExe=$((Test-Path -LiteralPath 'C:\Program Files\Google\Chrome\Application\chrome.exe'))"
Write-Output "GoogleChromeElevationService=$((Get-Service -Name 'GoogleChromeElevationService').Status)"

Write-Output '=== VERIFY GOOGLE UPDATER SERVICES, TASKS & ACL LOCKS ==='
& sc.exe query GoogleUpdaterService157.0.8089.0 | Out-String | ForEach-Object { Write-Output "sc gupdater: $($_.Trim())" }
& sc.exe query GoogleUpdaterInternalService157.0.8089.0 | Out-String | ForEach-Object { Write-Output "sc gupdater_int: $($_.Trim())" }
Write-Output "GoogleSystemTasks=$($null -ne (Get-ScheduledTask | Where-Object { $_.TaskPath -like '\GoogleSystem*' }))"

foreach ($ld in @(
  'C:\Program Files (x86)\Google\GoogleUpdater',
  'C:\Program Files (x86)\Google\Update',
  'C:\Users\Admin\AppData\Local\Google\GoogleUpdater'
)) {
  $testFile = Join-Path $ld 'probe.tmp'
  try {
    [System.IO.File]::WriteAllText($testFile, 'x')
    Write-Output "WRITE PROBE UNEXPECTEDLY SUCCEEDED: $ld"
  } catch {
    Write-Output "Write probe blocked (expected): $ld -> $($_.Exception.GetType().Name)"
  }
}

