Get-ItemProperty 'HKLM:\SOFTWARE\Policies\Google\Update' | Select-Object AutoUpdateCheckPeriodMinutes, UpdateDefault, 'Update{8A69D345-D564-463C-AFF1-A69D9E530F96}', DisableAutoUpdateChecksCheckboxValue | Format-List
Get-ItemProperty 'HKLM:\SOFTWARE\WOW6432Node\Policies\Google\Update' | Select-Object AutoUpdateCheckPeriodMinutes, UpdateDefault, 'Update{8A69D345-D564-463C-AFF1-A69D9E530F96}', DisableAutoUpdateChecksCheckboxValue | Format-List
